<template><div class="page"><el-form :model="query" inline><el-form-item label="成员账号"><el-input v-model="query.loginName" clearable /></el-form-item><el-form-item label="角色"><el-select v-model="query.roleCode" clearable><el-option label="BD Leader" value="BD_LEADER"/><el-option label="BD" value="BD"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable><el-option label="正常" value="0"/><el-option label="停用" value="1"/></el-select></el-form-item><el-button type="primary" @click="load">查询</el-button><el-button @click="reset">重置</el-button></el-form><div class="bar"><h2>我的团队</h2><el-button v-if="canCreate" type="primary" @click="visible=true">新增下级</el-button></div><el-table :data="rows" v-loading="loading" border><el-table-column prop="realName" label="成员"/><el-table-column prop="loginName" label="登录账号"/><el-table-column label="角色"><template #default="{row}">{{ role(row.roleCode) }}</template></el-table-column><el-table-column prop="parentLoginName" label="上级"/><el-table-column prop="directSubordinateCount" label="直属下级"/><el-table-column prop="guildCount" label="团队公会"/><el-table-column prop="monthFlow" label="本月流水（金币）"/><el-table-column label="状态"><template #default="{row}">{{row.status==='0'?'正常':'停用'}}</template></el-table-column><el-table-column label="开通方式"><template #default="{row}">{{ openMethod(row.openMethod) }}</template></el-table-column><el-table-column prop="createTime" label="开通时间"/></el-table><pagination v-show="total>0" v-model:page="query.pageNum" v-model:limit="query.pageSize" :total="total" @pagination="load"/><el-dialog v-model="visible" title="新增下级" width="520px"><el-form ref="formRef" :model="form" :rules="rules" label-width="110px"><el-form-item label="角色" prop="roleCode"><el-radio-group v-model="form.roleCode"><el-radio v-for="item in roles" :key="item.value" :label="item.value">{{item.label}}</el-radio></el-radio-group></el-form-item><el-form-item label="姓名" prop="realName"><el-input v-model="form.realName"/></el-form-item><el-form-item label="登录账号" prop="loginName"><el-input v-model="form.loginName"/></el-form-item><el-form-item label="关联 Woha ID" prop="wohaChatNo"><el-input v-model.number="form.wohaChatNo"/></el-form-item><el-form-item label="WhatsApp"><el-input v-model="form.whatsapp"/></el-form-item><el-form-item label="说明"><el-input v-model="form.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="submit">确定新增</el-button></template></el-dialog></div></template>
<script setup>import { addExternalSubordinate,getExternalProfile,listExternalTeamMembers } from '@/api/external/manager';import { ElMessageBox } from 'element-plus';const rows=ref([]),total=ref(0),loading=ref(false),visible=ref(false),formRef=ref(),profile=ref({}),query=reactive({pageNum:1,pageSize:10,loginName:'',roleCode:'',status:''}),form=reactive({roleCode:'BD',realName:'',loginName:'',wohaChatNo:undefined,whatsapp:'',remark:''}),rules={roleCode:[{required:true,message:'请选择角色'}],realName:[{required:true,message:'请输入姓名'}],loginName:[{required:true,message:'请输入登录账号'}],wohaChatNo:[{required:true,message:'请输入 Woha ID'}]};const canCreate=computed(()=>profile.value.permissions?.includes('CREATE_SUBORDINATE')&&profile.value.roleCode!=='BD');const roles=computed(()=>profile.value.roleCode==='SUPER_ADMIN'?[{value:'BD_LEADER',label:'BD Leader'},{value:'BD',label:'BD'}]:[{value:'BD',label:'BD'}]);const role=v=>v==='BD_LEADER'?'BD Leader':v==='BD'?'BD':v;const openMethod=v=>v==='OPERATION_OPEN'?'运营开通':v==='SUBORDINATE_OPEN'?'下级新增':v;async function load(){loading.value=true;try{const r=await listExternalTeamMembers(query);rows.value=r.rows;total.value=r.total}finally{loading.value=false}}function reset(){Object.assign(query,{pageNum:1,loginName:'',roleCode:'',status:''});load()}function submit(){formRef.value.validate(async ok=>{if(!ok)return;const r=await addExternalSubordinate(form);visible.value=false;await ElMessageBox.alert(`登录账号：${form.loginName}<br>初始密码：${r.initialPassword}`,'开通成功',{dangerouslyUseHTMLString:true});load()})}getExternalProfile().then(r=>profile.value=r.data);load()</script>
<style scoped>.page{padding:20px}.bar{display:flex;align-items:center;justify-content:space-between}.bar h2{font-size:18px}</style>
